using System.Text.Json.Serialization;

namespace OoplesFinance.StockIndicators.CompetitorBenchmarks;

internal sealed record ComparisonManifestEntry(string Id, string Kind, string[] EntryPoints,
    string Status, string? OoplesIndicator, string[] Outputs, string? ExclusionReason, string? CompetitorLimitation,
    [property: JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? AlternateComparison = null,
    [property: JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string[]? PendingConfigurations = null,
    [property: JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? OwnedDefinition = null);

internal static class ComparisonManifest
{
    // A throwing API cannot be timed. Its conventional counterpart can still be
    // independently verified and compared with an implemented package definition.
    internal static readonly IReadOnlyDictionary<string, string> AlternateComparisons = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["Trady.Indicator.ZigZag"] = "Skender.GetZigZag",
        ["Trady.Candlestick.ThreeBlackCrows"] = "TaLib.Candles.ThreeBlackCrows",
        ["Trady.Candlestick.ThreeWhiteSoldiers"] = "TaLib.Candles.ThreeWhiteSoldiers",
        ["Trady.Candlestick.UpsideGapTwoCrows"] = "TaLib.Candles.UpsideGapTwoCrows",
        ["Trady.Candlestick.PiercingLine"] = "TaLib.Candles.PiercingLine",
        ["Trady.Candlestick.StickSandwich"] = "TaLib.Candles.StickSandwich",
        ["Trady.Candlestick.HaramiCross"] = "TaLib.Candles.HaramiCross",
        ["Trady.Candlestick.Hammer"] = "TaLib.Candles.Hammer",
        ["Trady.Candlestick.HangingMan"] = "TaLib.Candles.HangingMan",
        ["Trady.Candlestick.InvertedHammer"] = "TaLib.Candles.InvertedHammer",
        ["Trady.Candlestick.ShootingStar"] = "TaLib.Candles.ShootingStar",
        ["Trady.Candlestick.LongLeggedDoji"] = "TaLib.Candles.LongLeggedDoji",
        ["Trady.Candlestick.Marubozu"] = "TaLib.Candles.Marubozu",
        ["Trady.Candlestick.SpinningTop"] = "TaLib.Candles.SpinningTop"
    };

    internal static readonly IReadOnlyDictionary<string, string> OwnedDefinitions = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["Trady.Candlestick.Stars"] = "ConventionalStarCandle",
        ["Trady.Candlestick.ShortShadow"] = "ShortShadowsCandle"
    };

    internal static ComparisonManifestEntry[] Create() => CompetitorApiCatalog.Discover().Select(Describe).ToArray();

    private static ComparisonManifestEntry Describe(CompetitorApi api)
    {
        var pair = ComparisonPairs.All.SingleOrDefault(pair => pair.Id == api.Id);
        CompetitorApiCatalog.Exclusions.TryGetValue(api.Id, out var reason);
        AlternateComparisons.TryGetValue(api.Id, out var alternateId);
        OwnedDefinitions.TryGetValue(api.Id, out var owned);
        var implementation = pair ?? (alternateId is null ? null : ComparisonPairs.Get(alternateId));
        var status = "pending";
        if (pair is not null) status = "paired";
        else if (reason is not null) status = "utility";
        else if (implementation is not null || owned is not null) status = "unavailable";
        string? limitation = pair?.MinimumInputCount > 1
            ? $"The pinned competitor rejects inputs shorter than {pair.MinimumInputCount} bars; verified by an executable boundary test." : null;
        if (api.Id.StartsWith("Trady.Candlestick.", StringComparison.Ordinal) && PercentileCandleComparison.IgnoresParameters(api.Id.Split('.').Last()))
            limitation = "Trady 3.2.8 ignores period and percentile arguments for this pattern; comparisons explicitly use its effective 20-bar default percentile.";
        if (api.Id == "Trady.Candlestick.LongLowerShadow")
            limitation = "Despite its name, Trady 3.2.8 tests a lower shadow strictly below its percentile (default 0.25). The Ooples counterpart is named for that formula.";
        if (api.Id == "TaLib.Functions.Bbands")
            limitation = "ClassicDeviationBands covers all nine average types with independently scaled upper/lower population deviations and explicit output masks. Both windows align to the current bar. Native MAMA with a deviation period above its phase lookback misaligns the packed center after changing the reported start; a separate native reference and regression retain that defect. Native uncentered variance can collapse large finite variation to zero; exact moments avoid this in Ooples. Float, compatibility, suppression, ranges, input/output aliases, zero widths and NaN acceptance have dedicated checks.";
        if (api.Id is "TaLib.Functions.Apo" or "TaLib.Functions.Ppo")
            limitation = "ClassicPriceOscillator orders fast/slow periods and covers all nine classical average methods, compatibility seeds and suppression. It rounds the full difference or percentage ratio once over rounded component averages with extended upper exponents, preventing intermediate subtraction overflow. Percentage mode returns zero for an exactly zero slow average. Wide component extrapolations are retained until final oscillator publication. Ooples supports period one; native APO/PPO require periods at least two. Native float, shifted ranges, aliases and nonfinite extreme arithmetic have independent checks.";
        if (api.Id == "TaLib.Functions.Ma")
            limitation = "ClassicMovingAverage covers all nine MAType formulas. Period one is identity and ignores all startup settings. EMA/DEMA/TEMA support first-price compatibility and per-stage suppression; KAMA/MAMA/T3 preserve their distinct startup. MAMA ignores periods above one. Native generic float, shifted ranges and aliases are independently verified. Native WMA uses an overflowing Int32 divisor for large periods; the counterpart uses wide arithmetic. Unknown method values are rejected by Ooples; native MA accepts them for period-one identity. Native rejects one-element input even for identity.";
        if (DeviationBandsComparison.Ids.Contains(api.Id))
            limitation = "WindowDeviationBands publishes complete-window mean, signed population-deviation bands, band position, exact-distribution Z-score and relative width with explicit masks. Ratios use the rounded center and extended scaled deviation before final band rounding, preserving narrow-band information. Skender exposes all six values with unscaled width; Trady exposes bands and a separate percentage width, supports period one and signed/zero factors, and uses decimal stages. Independent mathematical and native-stage references verify each contract and quote/tuple/generic routes.";
        if (api.Id == "QuanTAlib.Vidya")
            limitation = "DeviationRatioAdaptiveAverage uses short-window means for LongPeriod observations, then alpha times the population-deviation ratio. Exact moments, rounded ratio/gain/recurrence stages and lazy history prevent intermediate overflow. Native zero long deviation yields a persistent NaN recurrence; paired masks represent these as absent and direct regressions retain raw NaNs. Native Init retains its buffers. Independent references verify native staged arithmetic, revisions and source events.";
        if (api.Id is "TaLib.Functions.Dema" or "TaLib.Functions.Tema")
            limitation = "TA-Lib.NETCore 0.5.0 rejects period one with BadParam. Skender and the Ooples counterpart support it; executable boundary tests pin both behaviors.";
        if (WindowExtremeComparison.Names.Any(name => api.Id == "TaLib.Functions." + name))
            limitation = "TA-Lib.NETCore 0.5.0 rejects period one; Ooples supports it. Equal extrema select the most recent absolute zero-based index. Midpoint sums are evaluated without intermediate overflow in Ooples.";
        if (api.Id is "TaLib.Functions.Trima" or "TaLib.Functions.Sum")
            limitation = "TA-Lib.NETCore 0.5.0 rejects period one with BadParam. Ooples supports period one; executable boundary tests verify this difference.";
        if (api.Id is "Trady.Candlestick.BullishHarami" or "Trady.Candlestick.BearishHarami")
            limitation = "Directional object/generic APIs use open/close trends and ignore containedShadows. Their tuple wrappers run plain Harami, honor containedShadows, and ignore the trend period. Executable tests verify both mappings; tuple counterparts use StrictHaramiCandle.";
        if (api.Id is "TaLib.Candles.MorningStar" or "TaLib.Candles.EveningStar" or "TaLib.Candles.MorningDojiStar" or "TaLib.Candles.EveningDojiStar" or "TaLib.Candles.AbandonedBaby" or "TaLib.Candles.MatHold")
            limitation = "TA-Lib rounds the penetration product and threshold in binary64; Ooples evaluates the supplied binary64 parameter exactly. Strict boundary signals can differ (for example, a body of 5 with penetration 0.3 for star reversals or 0.1 for Mat Hold). Separate independent references verify both arithmetic contracts; executable regressions pin the discrepancy.";
        if (api.Id == "Trady.Candlestick.DarkCloudCover")
            limitation = "downTrendPeriodCount only delays reporting; no downtrend is tested. longPeriodCount and longThreshold are ignored. Delay zero accesses a future bar and fails at the end of input. Executable tests pin these behaviors; comparisons use positive delays.";
        if (api.Id is "Trady.Candlestick.UpsideTasukiGap" or "Trady.Candlestick.DownsideTasukiGap")
            limitation = "Trady 3.2.8 ignores sizeThreshold. Upside requires final open inside the previous body but does not bound final close within the gap. Downside requires final close strictly inside the full-range gap but does not constrain final open. Both require a prior high/low trend; executable tests pin object, generic and tuple routes.";
        if (api.Id is "Trady.Candlestick.BullishAbandonedBaby" or "Trady.Candlestick.BearishAbandonedBaby")
            limitation = "The bullish long-body component honors longPeriodCount/longThreshold; the bearish component ignores them and uses its 20-bar 0.75 defaults. Both use full-range isolation gaps and a prior high/low trend. Object, generic and tuple checks verify these definitions.";
        if (api.Id is "Trady.Candlestick.RisingThreeMethods" or "Trady.Candlestick.FallingThreeMethods")
            limitation = "Trady uses a variable-length backwards search, not a fixed five-candle pattern. Rejection barriers take precedence over overlapping long/short classifications; the most recent long anchor determines the result. Falling long bodies ignore requested period/longThreshold and use 20/0.75; its short-body window honors arguments. Independent scans and object/generic/tuple checks verify these rules.";
        if (TrendStarComparison.Names.Any(name => api.Id == "Trady.Candlestick." + name))
            limitation = "Trady uses prior high/low trends, percentile-long outer bodies (bearish fixed at 20/0.75), and a strict relative first-body midpoint target. Its decimal ratio rounds at boundaries; independent references verify the exact Ooples and native decimal contracts. A zero midpoint can throw DivideByZeroException in Trady; Ooples reports no match. Executable tests pin both differences, including the MoringinDojiStar tuple alias.";
        if (CompetitorApiCatalog.Unimplemented.Contains(api.Id))
            limitation = implementation is null ? "Trady 3.2.8 throws NotImplementedException; counterpart remains pending."
                : "Trady 3.2.8 throws NotImplementedException; no comparable timings. Ooples uses the independently verified alternate formula.";
        if (api.Id is "Skender.GetDoji" or "Skender.GetMarubozu")
            limitation = "Skender uses intermediate decimal ratios converted to binary64; Ooples compares exact supplied binary64 prices and percentage. Independent references verify boundary differences. Zero-range candle fractions are one; marubozu then reports BearSignal. All eleven calculated outputs and nullable price presence are checked.";
        if (PercentileComparison.Pairs.Any(pair => pair.Id == api.Id))
            limitation = "RollingPercentile evaluates exact supplied binary64 ranks and convex interpolation. QuanTAlib publishes an average before the full window; Trady has missing startup values. Independent references model native binary64 stage rounding or decimal conversion. Percentile endpoint/interior ranks, odd/even windows, and Trady generic/tuple routes are verified. QuanTAlib Percentile rejects period one; Ooples supports it.";
        if (WilderAverageComparison.Pairs.Any(pair => pair.Id == api.Id))
            limitation = "WilderMovingAverage uses alpha=1/period and a rounded exact convex recurrence. Skender and QuanTAlib Smma seed with a full-window mean; QuanTAlib also publishes expanding means before that seed. Trady ModifiedMovingAverage starts its recurrence from the first close. Independent references verify each seed and native binary64/decimal arithmetic; all startup values, period one and Trady tuple/generic routes are checked. QuanTAlib Rma is a different recurrence and remains pending.";
        if (SeededAtrComparison.Pairs.Any(pair => pair.Id == api.Id))
            limitation = "The initial candle only establishes previous close. ATR first appears at index period, seeded by true ranges at indices 1..period. Skender includes Tr, Atr and nullable Atrp; zero close makes only Atrp missing. Independent references model exact Ooples stages, native binary64 stages, and Trady decimal recurrence. Skender rejects period one; TA-Lib and Trady accept it. Ooples scalar ATR retains oversized unpublished ranges until their finite average; detailed outputs reject unrepresentable published ranges or percentages.";
        if (api.Id == "QuanTAlib.Atr")
            limitation = "Pinned QuanTAlib 1.0.0 Calc(TBar) leaves Input.IsNew false and forwards that stale flag to its EMA. Each internal update restores zero EMA state, so normal bar streams return (1/period)*trueRange, not smoothed ATR. The first candle uses high-low. ScaledTrueRange names this actual formula explicitly; conventional mean-seeded ATR is available separately. Package regressions cover direct and event-source routes. Exact Ooples scaling and native binary64 stage rounding have independent references. Manually assigning the inherited Input property can change the package behavior and is not the normal bar route.";
        if (api.Id == "TaLib.Functions.Natr")
            limitation = "Ooples computes signed 100*seededATR/close, with zero on zero-close bars and during startup; period one remains normalized and later bars never revise earlier results. TA-Lib 0.5.0 instead returns raw true range for period one. A later zero close overwrites its first output and leaves the current slot untouched; the timed adapter explicitly zero-initializes its buffer. Independent references verify the conventional formula and these native defects separately. Sentinel, prefix-stability, period-one and corruption regressions pin the differences. Ordinary positive-price timings exercise matching formulas.";
        if (WindowRegressionComparison.Pairs.Any(pair => pair.Id == api.Id))
            limitation = "WindowLinearRegression selects an independently rounded endpoint, one-step forecast, slope, local intercept, or slope angle in degrees using x=0..period-1. This local intercept differs from the existing LinReg global-series intercept. Only the selected value is published, so oversized unselected readings do not invalidate finite results. Independent rational references verify partial/full windows, expiration, local coordinates, and extreme/subnormal cases. These competitors require period >=2; Ooples supports period one with zero slope/angle and price readings equal to close.";
        if (api.Id == "TaLib.Functions.MacdExt")
            limitation = "ClassicMacd supports every fast/slow/signal combination of the nine classical averages, sorted periods with their methods, aligned seed boundaries, compatibility seeds and suppression. Wide rounded internal values feed the signal without premature overflow. Native period-one signal requests can fail when their intermediate input has one element; the owner defines positive period-one identities and rejects unknown methods. Independent rational/grid/native references cover all method combinations, subranges, aliases, extreme values, lifecycle and mutations.";
        if (api.Id == "TaLib.Functions.HtTrendline")
            limitation = "DelayedHilbertTrendline starts Hilbert filtering at index 37 and publishes from 63+suppression. The rounded smoothed period selects a close-price mean, followed by 4/3/2/1 weighting. Exact rounded wide stages keep finite averages and controls at extreme prices. Native WMA/product overflow can turn the cycle period into NaN and its integer length into zero; the native reference retains the resulting zero means instead of hiding the discrepancy. Shifted ranges restart filter history; native suppression lookback can wrap, while owned state remains bounded with Int64 publication. Independent rational/grid/native, float/double, alias, lifecycle, chaining and mutation checks cover the contract.";
        if (
            api.Id
            is "TaLib.Functions.HtDcPhase"
                or "TaLib.Functions.HtSine"
                or "TaLib.Functions.HtTrendMode"
        )
            limitation =
                "DelayedHilbertPhase/Sine/TrendMode retain index-37 filtering and index-63 publication plus suppression. Rounded wide projections preserve exact zero/sign branches and finite controls. Math.Atan/Sin define phase and sine controls; trend votes compare distinct values directly and the 1.5% trend deviation compares an exact ratio. Native IEEE WMA/projection overflow, NaN phase/sine and resulting trend votes remain explicitly modeled. Native shifted ranges reseed history and oversized suppression can wrap lookback; owned histories are fixed-size. Rational/grid/native references verify complete outputs, float/double aliases, extreme/subnormal and zero inputs, lifecycle, chaining and mutations.";
        if (api.Id == "Trady.Indicator.ZigZag")
            limitation = "Trady 3.2.8 ZigZag throws NotImplementedException and has no formula to reproduce or time. Its alternate is ZigZagSnapshot, independently verified against the Skender percentage-reversal convention with all four outputs.";
        if (api.Id == "Skender.GetZigZag")
            limitation = "ZigZagSnapshot covers close/high-low percentage reversals, latest equal extremes, the unconfirmed final endpoint, pivot types and both retracement lines. Exact signed percentage comparisons and once-rounded convex interpolation preserve tiny/wide values. Initial zero prices cannot establish percentage changes; the first line is absent except its endpoint. Independent rational/native-decimal references cover every output and mask. Retrospective endpoints repaint when later bars arrive. Trady ZigZag is a throwing stub; its owned alternate is this verified convention, not an attributed Trady formula.";
        if (api.Id is "Skender.GetRenko" or "Skender.GetRenkoAtr")
            limitation = "RenkoSnapshot lazily emits complete timestamp/OHLCV/direction bricks, including repeated timestamps and equal volume allocation across multi-brick candles. Exact binary64 thresholds/counts and wide volume sums avoid intermediate overflow; native decimal stages have independent references. Initial baseline precision comes from one fewer decimal place in the binary64 brick size round-trip spelling, while native uses decimal brick precision. ATR mode uses the final verified Wilder ATR for the entire retrospective chart, retaining binary64 brick size rather than native decimal conversion; later input repaints earlier bricks. Undefined/zero ATR yields no bricks. Arbitrarily large counts can be consumed lazily without allocating a count-sized array. Both timestamp words are verified exactly.";
        if (api.Id == "QuanTAlib.Jma")
            limitation = "JurikAdaptiveSnapshot preserves Quan volatility windows, phase clamping, band adaptation and the three-stage recurrence. Period one retains the initial price. Histories grow lazily; wide once-rounded recurrence stages avoid intermediate overflow and retain tiny differences, rejecting only unrepresentable published results. Independent wide and staged-binary64 references cover periods, phase clamps, volatility history and output mutations. Native Init retains price/volatility histories, so comparisons use fresh instances. Owned accepts positive periods and finite phase.";
        if (api.Id == "Skender.GetHurst")
            limitation = "HurstSnapshot publishes both raw and Anis-Lloyd corrected exponents, preserving minimum-eight chunks, oldest-remainder removal and at most 32 partitions. Undefined regressions and nonpositive-price windows are absent. Positive extreme ratios use log differences to avoid division overflow/underflow. Owned AL corrections use a half-integer gamma recurrence through size 340; independent Lanczos and pairwise-regression references cover both outputs within an explicit 1e-10 absolute/relative budget. Periods below 20 are rejected; unavailable maximum-period history allocates no period-sized buffers.";
        if (api.Id == DynamicMomentumComparison.Id)
            limitation = "DynamicMomentumSnapshot selects a fixed-period nullable Wilder RSI from the complete original history for each bar. Population deviation divides by calendar window size while its mean skips missing values; smoothed deviation also skips missing values after calendar startup. Exact moments and once-rounded deviation/mean/volatility stages preserve tiny and wide inputs. Period clamping precedes integer conversion, avoiding native integer overflow. Independent pairwise-distance and decimal references cover selected periods, nullable inputs, output masks and mutations. Native decimal rounding can select different periods; its implementation repeatedly reconstructs volatility histories. Owned requires positive periods and ordered positive limits.";
        if (ParabolicComparison.Ids.Contains(api.Id))
            limitation = "ParabolicStopSnapshots separates TA classic/extended, Skender confirmed and Trady five-bar-seeded conventions. Exact comparisons and once-rounded wide updates preserve finite clamp/reversal decisions; unrepresentable published stops are rejected. Extended supports signed starts, reversal offsets and independent long/short accelerations. Confirmed removes the initial guessed trend through its first reversal; FourBar tests the preceding candle and retains finite signed step support. Independent wide/native-double/native-decimal references verify all masks, startup, ties, parameters, extremes, quote/tuple routes and mutations. Trady 3.2.8 sequential Compute replays and overwrites the previous cached transition with advanced state; its native reference reproduces that defect while FourBar evaluates each transition once. Native staged differences/updates may overflow and TA singleton inputs are rejected.";
        if (api.Id == "Skender.GetKvo")
            limitation = "KlingerVolumeSnapshot preserves the two-bar force startup, direction/range branches and independently mean-seeded fast/slow/signal EMAs. Exact HLC comparisons and ranges avoid intermediate overflow; complete force and EMA stages round once with extended upper exponents. Both nullable outputs, startup, configurations, zero/cancelling ranges, wide/subnormal candles, final overflow and mutations have independent references. Native double-stage and quote conversion behavior are modeled separately. Maximum periods use constant storage; native derived period arithmetic can overflow.";
        if (api.Id == "Skender.GetPivots")
            limitation = "PivotTrendSnapshot reuses strict Williams fractals and connects successive unequal anchors within the maximum distance. All six outputs retain independent masks; lines include both endpoints and trends start one bar after the earlier anchor. Equal pivots reset the anchor without painting. Once-rounded exact interpolation avoids decimal intermediate overflow. Independent consecutive-anchor/decimal-stage references verify future confirmation, expiration, equal anchors, close/high-low routes, huge spans, wide interpolation and every output/mask mutation.";
        if (api.Id is "QuanTAlib.Fwma" or "QuanTAlib.Afirma")
            limitation = "FibonacciWeightedSnapshot uses exact integer Fibonacci coefficients, newest-first available-prefix normalization, and period-one identity; native period one throws and long floating kernels overflow. WindowedSincSnapshot models Afirma's published oldest-first response with newest-price extension, five binary64 trigonometric windows and once-rounded complete ratios. Afirma's cubic extrapolation is unused in its output. Undefined/zero kernels are rejected; native Hann taps one/two produce NaN. Independent doubling-identity Fibonacci and staged trigonometric/native normalization references verify startup, configurations, extremes, repeated/prefix calls and mutations. Kernel storage scales with the requested period/taps; no new public maximum is imposed.";
        if (api.Id == "QuanTAlib.Maaf")
            limitation = "MedianAdaptiveSnapshot preserves raw first-three prices, four-price 1/2/2/1 smoothing, descending-by-two upper-median windows and a signed median error denominator. The final filter length is at least three; finite signed thresholds are supported. Complete smoothing updates round once and error thresholds compare exact ratios, preserving wide and tiny distinctions. Independent order-statistic/rational and staged-native references cover odd/even periods, startup, negative/zero medians, threshold neighbors, wide/subnormal inputs, huge periods, fresh/prefix calls and corrupted outputs. Native staged differences/products can overflow; owned history grows lazily.";
        if (api.Id == "QuanTAlib.Rvi")
            limitation = "RelativeVolatilitySnapshot uses sample deviations of up/down changes, then available-history simple averages and a bounded ratio; previous close starts at zero. Exact changes and once-rounded deviation/mean stages use extended upper exponents, preserving finite ratios after unpublished overflow. An independent pairwise squared-distance/root oracle and native scalar-deviation/SIMD-mean oracle verify every output, period/startup boundaries, huge periods, wide/subnormal changes and corruption. Native squared deviations can underflow to zero and inherited reset retains nested histories; both limitations have explicit regressions. Owned calls start fresh and histories grow lazily.";
        if (api.Id == "QuanTAlib.Htit")
            limitation = "OldestFirstHilbertTrendline preserves the native oldest-first buffer convention, not a standard Hilbert estimator. The two-element phasor buffers compare current phasors with themselves, making the finite imaginary discriminator zero; the clamped period is consequently price-independent and tends to six. Owned evaluates that reduced formula with exact once-rounded means, avoiding unused phasor overflow. First ten outputs are prices; subsequent oldest-first four-mean weights are 4/3/2/1. Independent full native phasor and rational reduced references verify startup, all trajectories, lifecycle/source, extremes and corruption. Native inherited Init leaves histories and last period intact; the explicit reset regression records this limitation.";
        if (api.Id == "Skender.GetConnorsRsi")
            limitation = "ConnorsStrengthSnapshot publishes all four nullable components, preserving independent close RSI, the delayed streak RSI, inclusive return-rank window, initial zero return and integer-truncated percentile. Exact return ordering avoids overflow and false ties; nonpositive previous closes remain excluded. Wilder strength reuses the verified wide-exponent engine and the final component mean rounds once. Independent direct-run streak/rational-rank and staged native references cover startup, configurations, quote/tuple routes, prefixes/repeated calls, huge periods, tiny/wide/negative prices and every output/mask mutation. Native rank arithmetic can erase distinctions or overflow; huge derived warmup periods overflow. Owned histories grow lazily and period sums use Int64.";
        if (api.Id == "Skender.GetStc")
            limitation = "SchaffTrendCycleSnapshot retains Skender's single-stochastic STC convention: independently mean-seeded fast/slow EMAs, complete cycle window on MACD, then three-value SMA. Flat windows contribute zero; all startup masks are explicit. Reuses the verified EMA arithmetic with extended upper exponents and lazy cycle history, so overflowing unpublished MACD cannot poison bounded output. Independent rational-grid and native staged references cover configurations, startup, tiny/wide inputs, quote/tuple routes, repeat/prefix calls and output/presence mutations. Native zero cycle fails in its nested stochastic despite permissive outer validation; owned rejects nonpositive cycles immediately.";
        if (api.Id is "Skender.GetRollingPivots" or "Skender.GetPivotPoints")
            limitation = "PivotLevelSnapshots supports Standard, Camarilla, DeMark, Fibonacci and Woodie formulas, all nine nullable levels, rolling offsets and hour/day/invariant-week/month windows. Exact decimal-rational constants and complete final-level rounding avoid intermediate overflow. Calendar identities include year/date; native short hour/day/week/month keys can merge distinct sparse windows. Native decimal stage rounding/overflow and Int32 rolling-boundary overflow remain separate references and regressions. Current-open Woodie and rolling DeMark semantics, prior-open calendar DeMark, missing formula levels, sparse boundaries, huge periods, all output masks and mutations are verified.";
        if (api.Id == "Skender.GetStdDevChannels")
            limitation = "RegressionChannelSnapshot fits nonoverlapping blocks backward from the last row; leading incomplete rows are absent and BreakPoint remains a defined false value there. Null period fits the entire input, requiring at least two rows. Reuses the verified regression-moment engine with exact fitted positions, rounded population deviation and wide channel arithmetic. Native global-coordinate binary64 regressions and the unused final-line decimal cast inside CalcSlope have separate references; that cast can reject prices whose channels would otherwise be finite. Block shifts on append, all outputs, quote/tuple/reusable routes, extreme inputs, genuine final overflow and mutations are verified.";
        if (api.Id == "Skender.GetVolatilityStop")
            limitation = "VolatilityStopSnapshot preserves the retrospective removal of every row through the first reversal; if no reversal exists, the initial guessed segment remains. Prior-bar mean-seeded ATR determines the stop. All four nullable outputs, strict reversal ties, prefix erasure on append, supplied ordering, wide retained-output validation, and independent grid/native references are verified. Native quote decimal range, IEEE overflow, and nonfinite multiplier acceptance remain separate limitations.";
        if (api.Id == "Skender.GetFisherTransform")
            limitation = "WindowFisherTransform uses available windows, initial Fisher zero and absent trigger, flat-window position reset, and +/-0.99 to +/-0.999 clamping. Exact rounded range ratios and overflow-safe midpoint preserve bounded controls; binary64 smoothing and Math.Log define the transform. Default midpoint and explicit close routes have independent rational/grid/native references. Native range subtraction overflow can erase Fisher/trigger via NaN-to-null propagation; native quote decimal midpoint limits remain visible. Lifecycle, boundaries, extreme inputs, chaining, and every output/mask mutation are verified.";
        if (api.Id is "Skender.GetAtrStop" or "Skender.GetSuperTrend")
            limitation = "SeededAtrTrailingStop supports close, high/low, and midpoint candidate bands. Mean-seeded Wilder ATR publishes at index period; midpoint initializes direction against midpoint, other bases against previous close. Upper/lower bands trail independently and close equal to the active band selects bearish/upper output. Owned midpoint, width, bands and ATR stages use rounded wide arithmetic and exact comparisons. Native binary64 stages and final decimal casts are independently modeled, including decimal overflow and nonfinite multipliers accepted by native validation. Complete stop/band/presence trajectories, all bases, ties, wide cancellation, lifecycle, chaining and mutations are verified.";
        if (api.Id is "QuanTAlib.Frama" or "QuanTAlib.Dsma")
            limitation = "RangeFractalAverage uses the two half-window ranges with prefix means; the epsilon-adjusted exact range ratio rounds before log/exp gain calculation. FilteredDeviationAverage uses the two-pole filtered price-minus-average residual and a fixed-period RMS, including partial windows; its normalized magnitude rounds the exact square-root ratio once. Both use rounded wide intermediates and convex updates, lazy history, and independent rational/grid/native references. Native SIMD prefix/square sums, IEEE range/filter overflow, DSMA NaN scale acceptance, and DSMA Init retaining old RMS samples remain explicit limitations. Odd/even periods, scale boundaries, updates, owned lifecycle, chaining and mutations are verified.";
        if (api.Id == "Skender.GetHtTrendline")
            limitation = "SeededHilbertTrendline publishes input through index 10, then a 4/3/2/1 weighted dominant-cycle mean; smooth price starts at index 6 and zero cycle lengths remain absent. The default high/low midpoint and explicit close route have independent rational/grid/native references. Owned logical stages use rounded wide arithmetic; native decimal midpoint and IEEE product/mean overflow remain separate, visible limitations. All three outputs, presence, startup, lifecycle, chaining, and mutations are verified.";
        if (api.Id is "TaLib.Functions.HtDcPeriod" or "TaLib.Functions.HtPhasor")
            limitation = "HilbertCyclePeriod and HilbertPhasor use delayed zero-seeded filters and publish from 32+suppression. Exact logical-stage rounding with extended upper exponents preserves finite cycle controls despite oversized unpublished products. Native IEEE product/WMA overflow and subnormal behavior have separate references; native shifted ranges restart filter history from the requested start minus lookback. Huge native suppression can overflow Int32 lookback; owned suppression uses Int64 with fixed storage. Float/double, aliases, startup, chaining, lifecycle and output/presence mutations are independently checked.";
        if (api.Id is "TaLib.Functions.Stoch" or "TaLib.Functions.StochF")
            limitation = "ClassicStochastic uses zero-flat complete high/low windows and independent classical K/D averages, with both outputs withheld until D starts. K period one selects fast stochastic. Exact differences and wide rounded internal values preserve finite cancellation; published overflow is rejected. Native arithmetic divides the range by 100 before dividing the numerator, exposing different rounding, underflow and nonfinite results. Native one-element intermediate buffers fail; the owner defines positive period-one identities and lazy huge periods. Independent rational/grid/native references cover all method combinations, compatibility seeds, suppression, float/double ranges and aliases, lifecycle, chaining and mutations.";
        if (api.Id == "Skender.GetStoch")
